<?php
declare(strict_types=1);
require_once __DIR__.'/auth.php';require_once __DIR__.'/read-model.php';require_once __DIR__.'/campaign-store.php';
try{kalite_filo_admin_start_session();kalite_filo_admin_require_authentication();if(($_SERVER['REQUEST_METHOD']??'')==='GET'){$snapshot=kalite_filo_admin_content_snapshot();$rows=[];for($page=1;$page<=1000;$page++){$slice=kalite_filo_admin_contact_page(kalite_filo_admin_contact_store_path(),$page,100);$rows=[...$rows,...$slice['records']];if(!$slice['hasNext'])break;}$summary=kalite_filo_admin_campaign_audience_summary($rows,(string)kalite_filo_admin_config()['environment']);kalite_filo_admin_json(['campaigns'=>kalite_filo_admin_campaign_records(),'audienceSummary'=>$summary,'referenceOptions'=>kalite_filo_admin_campaign_reference_options($snapshot),'deliveryEnabled'=>false]);}kalite_filo_admin_require_method('POST');kalite_filo_admin_require_same_origin();kalite_filo_admin_require_csrf();kalite_filo_admin_require_roles(['owner','admin','marketing']);$body=kalite_filo_admin_read_json(262144);$lock=kalite_filo_admin_lock_campaign_store();try{$records=kalite_filo_admin_campaign_records();$campaign=kalite_filo_admin_freeze_campaign_references(kalite_filo_admin_normalize_campaign($body),kalite_filo_admin_content_snapshot());$records[]=$campaign;kalite_filo_admin_write_campaign_records($records);}finally{kalite_filo_admin_unlock_campaign_store($lock);}kalite_filo_admin_audit('campaign_create','success',['id'=>$campaign['id']]);kalite_filo_admin_json(['campaign'=>$campaign],201);}catch(InvalidArgumentException $e){kalite_filo_admin_json(['error'=>'validation_failed'],422);}catch(Throwable $e){error_log('Campaigns failed: '.$e->getMessage());kalite_filo_admin_json(['error'=>'service_unavailable'],503);}
